from pathlib import Path
import re

P=Path('index.html')
s=P.read_text(encoding='utf-8')

css='''
/* ADVANCED_TECH_CHART */
.overlay-legend{margin-top:11px;padding-top:10px;border-top:1px solid var(--line)}.overlay-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-top:8px}.overlay-pattern{background:#0c1621;border:1px solid #27394b;border-radius:10px;padding:9px}.overlay-pattern .head{display:flex;justify-content:space-between;gap:8px;align-items:center}.overlay-pattern b{font-size:12px}.overlay-pattern .meta{font-size:10px;color:var(--muted);margin-top:4px}.overlay-pattern .levels{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin-top:7px}.overlay-pattern .levels span{font-size:9px;background:#09131d;border:1px solid #223547;border-radius:7px;padding:5px}.signal-chips{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.signal-chip{font-size:9px;border:1px solid #33495f;border-radius:999px;padding:4px 7px;background:#0c1621}.overlay-note{font-size:10px;color:var(--muted);line-height:1.45;margin-top:7px}@media(max-width:700px){.overlay-grid{grid-template-columns:1fr}.overlay-pattern .levels{grid-template-columns:1fr}}
'''
if '/* ADVANCED_TECH_CHART */' not in s:
    s=s.replace('</style>',css+'</style>')

js=r'''
/* ADVANCED_TECH_CHART_JS */
function overlayTone(b){return /Bull/i.test(String(b))?'good':/Bear/i.test(String(b))?'bad':'neutral'}
function overlayPatternLegend(t){const ps=t?.advanced_chart_patterns||[],ds=t?.divergence_signals||[],ev=t?.chart_signal_events||[];const cards=ps.slice(0,6).map(p=>`<div class="overlay-pattern"><div class="head"><b class="${overlayTone(p.bias)}">${p.name}</b><span class="pass-pill ${p.status==='Confirmed'?'pass':'fail'}">${p.status||'Candidate'}</span></div><div class="meta">${p.bias||'Neutral'} • structural quality ${p.structural_quality??'—'}/100 • ${p.confidence||'—'} confidence</div><div class="levels"><span>Confirm<br><b>${money(p.confirmation)}</b></span><span>Invalidate<br><b>${money(p.invalidation)}</b></span><span>Measured target<br><b>${money(p.target)}</b></span></div><div class="small">${p.detail||''}</div></div>`).join('');const dchips=ds.map(x=>`<span class="signal-chip ${overlayTone(x.bias)}">${x.name} • Q${x.quality??'—'}</span>`).join('');const echips=ev.slice(-8).map(x=>`<span class="signal-chip ${overlayTone(x.bias)}">${x.date} • ${x.name}</span>`).join('');return `<div class="overlay-legend"><div class="label">Machine-detected chart structure</div><div class="overlay-grid">${cards||'<div class="small">No high-quality advanced pattern candidate right now.</div>'}</div>${dchips?`<div class="small" style="margin-top:8px"><b>Divergences</b></div><div class="signal-chips">${dchips}</div>`:''}<div class="small" style="margin-top:8px"><b>Recent signal events</b></div><div class="signal-chips">${echips||'<span class="small">No recent event markers.</span>'}</div><div class="overlay-note">Pattern quality scores geometry/recency/confirmation only. It is not predictive accuracy. Candidate patterns require their confirmation level; PASS/FAIL in the model audit remains the predictive standard.</div></div>`}
const techOverlayPlugin={id:'techOverlay',afterDatasetsDraw(chart,args,opts){const o=opts||{},ctx=chart.ctx,area=chart.chartArea,x=chart.scales.x,y=chart.scales.y,labels=chart.data.labels||[];ctx.save();ctx.font='9px sans-serif';const pxDate=d=>{const i=labels.indexOf(d);return i>=0?x.getPixelForValue(i):null};(o.levels||[]).slice(0,6).forEach((lv,i)=>{const p=Number(lv.price);if(!Number.isFinite(p)||p<y.min||p>y.max)return;const yy=y.getPixelForValue(p);ctx.setLineDash(lv.kind?.includes('trigger')?[5,4]:[2,4]);ctx.lineWidth=1;ctx.strokeStyle=lv.kind==='support'?'rgba(91,211,154,.55)':lv.kind==='resistance'?'rgba(255,125,134,.55)':lv.kind==='bull_trigger'?'rgba(91,211,154,.8)':'rgba(255,125,134,.8)';ctx.beginPath();ctx.moveTo(area.left,yy);ctx.lineTo(area.right,yy);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=ctx.strokeStyle;ctx.fillText(`${lv.label} ${money(p)}`,area.right-92,yy-3)});(o.patterns||[]).slice(0,4).forEach(p=>{(p.segments||[]).forEach(seg=>{const x1=pxDate(seg.x1),x2=pxDate(seg.x2),y1=Number(seg.y1),y2=Number(seg.y2);if(x1==null||x2==null||!Number.isFinite(y1)||!Number.isFinite(y2))return;ctx.strokeStyle=/Bull/i.test(p.bias)?'rgba(91,211,154,.75)':/Bear/i.test(p.bias)?'rgba(255,125,134,.75)':'rgba(239,190,104,.7)';ctx.lineWidth=1.4;ctx.setLineDash(p.status==='Confirmed'?[]:[5,4]);ctx.beginPath();ctx.moveTo(x1,y.getPixelForValue(y1));ctx.lineTo(x2,y.getPixelForValue(y2));ctx.stroke();ctx.setLineDash([])});const xx=pxDate(p.end);if(xx!=null){const yy=y.getPixelForValue(Number(p.confirmation??chart.data.datasets[0]?.data?.[labels.indexOf(p.end)]));if(Number.isFinite(yy)){ctx.fillStyle=/Bull/i.test(p.bias)?'#5bd39a':/Bear/i.test(p.bias)?'#ff7d86':'#efbe68';ctx.fillText(`${p.name} • ${p.status}`,Math.max(area.left+4,Math.min(xx-35,area.right-110)),Math.max(area.top+12,yy-8))}}});const markers=[...(o.divergences||[]),...(o.events||[])].slice(-9);markers.forEach(m=>{const xx=pxDate(m.date),pp=Number(m.price);if(xx==null||!Number.isFinite(pp)||pp<y.min||pp>y.max)return;const yy=y.getPixelForValue(pp);ctx.beginPath();ctx.arc(xx,yy,3.2,0,Math.PI*2);ctx.fillStyle=/Bull/i.test(m.bias)?'#5bd39a':/Bear/i.test(m.bias)?'#ff7d86':'#efbe68';ctx.fill()});ctx.restore()}}
'''
if '/* ADVANCED_TECH_CHART_JS */' not in s:
    s=s.replace('function tradingViewSection(asset)',js+'\nfunction tradingViewSection(asset)')

new_draw=r'''function drawChart(t,asset){const el=document.getElementById('priceChart');if(!el)return;if(chart){chart.destroy();chart=null}const rows=t.chart||[];if(!rows.length)return;const series=k=>rows.map(x=>Number.isFinite(Number(x[k]))?Number(x[k]):null), close=series('close'), overlay=t.chart_overlay||{};chart=new Chart(el,{type:'line',plugins:[techOverlayPlugin],data:{labels:rows.map(x=>x.date),datasets:[{label:asset==='gold'?'Gold futures':'Silver futures',data:close,borderWidth:2.2,pointRadius:0,borderColor:asset==='gold'?'#d9b55f':'#c8d1db',tension:.08},{label:'EMA20',data:series('ema20'),borderWidth:1.15,pointRadius:0,borderColor:'#72a8ff'},{label:'EMA50',data:series('ema50'),borderWidth:1.05,pointRadius:0,borderColor:'#a786ff'},{label:'EMA200',data:series('ema200'),borderWidth:1,pointRadius:0,borderColor:'#efbe68',borderDash:[6,4]},{label:'VWAP20',data:series('vwap20'),borderWidth:1,pointRadius:0,borderColor:'#5bd39a',borderDash:[3,3]},{label:'BB upper',data:series('bb_upper'),borderWidth:.8,pointRadius:0,borderColor:'rgba(145,164,184,.55)',borderDash:[2,4]},{label:'BB lower',data:series('bb_lower'),borderWidth:.8,pointRadius:0,borderColor:'rgba(145,164,184,.55)',borderDash:[2,4]}]},options:{responsive:true,interaction:{mode:'index',intersect:false},plugins:{legend:{labels:{color:'#b8c6d4',boxWidth:12,font:{size:10}}},techOverlay:{levels:overlay.levels||[],patterns:overlay.patterns||[],divergences:overlay.divergences||[],events:overlay.events||[]}},scales:{x:{ticks:{color:'#71859b',maxTicksLimit:9},grid:{display:false}},y:{ticks:{color:'#71859b'},grid:{color:'rgba(120,145,170,.08)'}}}}});const card=el.parentElement;let box=card.querySelector('.overlay-legend');if(box)box.remove();el.insertAdjacentHTML('afterend',overlayPatternLegend(t))}'''
s,n=re.subn(r'function drawChart\(t,asset\)\{.*?\}\nasync function loadAsset',new_draw+'\nasync function loadAsset',s,count=1,flags=re.S)
if n!=1: raise RuntimeError('Could not replace drawChart')

# TradingView: only use study identifiers demonstrated in current official widget docs.
if "studies:['StochasticRSI@tv-basicstudies','MASimple@tv-basicstudies']" not in s:
    s=s.replace("hide_volume:false,calendar:false", "hide_volume:false,studies:['StochasticRSI@tv-basicstudies','MASimple@tv-basicstudies'],calendar:false")

P.write_text(s,encoding='utf-8')
print('Advanced chart overlays patched')
